+/** Typst strings are not JSON strings: control characters use \u{...}. */
+export function typstString(value: string): string {
+  return '"' + value.replace(/["\\\u0000-\u001f\u007f]/g, (c) => {
+    if (c === '"' || c === "\\") return "\\" + c;
+    if (c === "\n") return "\\n";
+    if (c === "\r") return "\\r";
+    if (c === "\t") return "\\t";
+    return "\\u{" + c.charCodeAt(0).toString(16) + "}";
+  }) + '"';
+}
+
+const text = (value: string) => value ? `#text(${typstString(value)})` : "";
+const number = (raw: string | null | undefined, fallback: number, min: number, max: number) => {
+  if (raw == null || raw.trim() === "") return fallback;
+  const n = Number(raw);
+  return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : fallback;
+};
+
+function color(raw: string): string | null {
+  if (/^#[\da-f]{3}(?:[\da-f]{3})?$/i.test(raw)) return `rgb(${typstString(raw)})`;
+  const rgb = /^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)(?:\s*,\s*([\d.]+))?\s*\)$/i.exec(raw);
+  if (!rgb) return null;
+  const channels = rgb.slice(1, 4).map((n) => Math.min(255, Number(n)));
+  if (rgb[4] != null) channels.push(Math.round(Math.min(1, Number(rgb[4])) * 255));
+  return `rgb(${channels.join(", ")})`;
+}
+
+/** Never interpolate manuscript text as executable Typst markup. */
