+    if (el.style.fontWeight === "bold" || Number(el.style.fontWeight) >= 600) args.push('weight: "bold"');
+    if (el.style.fontStyle === "italic") args.push('style: "italic"');
+    if (args.length) body = `#text(${args.join(", ")})[${body}]`;
