+async function loadAssets(document: TypstDocument, signal: AbortSignal): Promise<TypstCompileRequest["assets"]> {
+  const assets: TypstCompileRequest["assets"] = [];
+  const cache = new Map<string, Uint8Array>();
+  let total = 0;
+  for (const asset of document.assets) {
+    signal.throwIfAborted();
+    const url = new URL(asset.url, window.location.href);
+    if (!["https:", "http:", "blob:", "data:"].includes(url.protocol)) {
+      throw new Error("An image uses a source that cannot be exported. Save it in the folio first.");
