+          const { done, value } = await reader.read();
+          if (done) break;
+          length += value.byteLength;
+          if (length > MAX_IMAGE_BYTES || total + length > MAX_TOTAL_IMAGE_BYTES) {
+            await reader.cancel();
+            throw new Error("This folio has too much image data for Typst export. Use PDF… or reduce the image sizes.");
+          }
+          chunks.push(value);
+        }
+      } finally {
